class Solution {
public:
    vector<int> distributeCandies(int candies, int num_people) {
        int n = num_people;
        long long c = candies;
        // Binary search for largest K with K*(K+1)/2 <= c
        long long lo = 0, hi = 2000000LL;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (mid * (mid + 1) / 2 <= c)
                lo = mid;
            else
                hi = mid - 1;
        }
        long long K = lo;
        vector<int> ans(n, 0);
        for (int i = 0; i < n; i++) {
            if ((long long)(i + 1) <= K) {
                long long ci = (K - (long long)(i + 1)) / n + 1;
                long long sum = ci * (i + 1) + (long long)n * ci * (ci - 1) / 2;
                ans[i] = (int)sum;
            }
        }
        long long rem = c - K * (K + 1) / 2;
        int idx = (int)(K % n);
        ans[idx] += (int)rem;
        return ans;
    }
};
